package com.tekwatt.firmware.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="firmware_update_jobs")public class FirmwareUpdateJob{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false)private UUID chargerId;@Column(nullable=false)private UUID firmwarePackageId;@Column(nullable=false,length=20)private String ocppVersion;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private UpdateStatus status;@Column(nullable=false)private Instant scheduledAt;@Column(length=1000)private String statusInfo;@Column(nullable=false,updatable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;protected FirmwareUpdateJob(){}public FirmwareUpdateJob(UUID t,UUID c,UUID p,String ocpp,Instant scheduled){id=UUID.randomUUID();tenantId=t;chargerId=c;firmwarePackageId=p;ocppVersion=ocpp;status=UpdateStatus.SCHEDULED;scheduledAt=scheduled;createdAt=Instant.now();updatedAt=createdAt;}public void update(UpdateStatus s,String info){status=s;statusInfo=info;updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getChargerId(){return chargerId;}public UUID getFirmwarePackageId(){return firmwarePackageId;}public String getOcppVersion(){return ocppVersion;}public UpdateStatus getStatus(){return status;}public Instant getScheduledAt(){return scheduledAt;}public String getStatusInfo(){return statusInfo;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
